const trig = $('Source Input').first().json || {};
const message = trig.message || '';
const ragChunks = ($json && $json.chunks) ? $json.chunks : [];
const sources = [];
const warnings = [];
const seen = new Set();

function add(s) {
  if (!s || !s.text) return;
  const key = (s.type||'') + '|' + (s.url||'') + '|' + String(s.text).slice(0,80);
  if (seen.has(key)) return;
  seen.add(key);
  sources.push(s);
}
function strip(html) {
  return String(html)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ').trim();
}

// 1) RAG knowledge-base chunks
for (const c of ragChunks) {
  add({ type: 'rag', title: c.original_filename || 'knowledge base',
        text: c.text, url: null, citation: c.original_filename || 'RAG' });
}

// 2) URLs in the message: article extraction / YouTube transcript
const urls = message.match(/https?:\/\/[^\s)]+/g) || [];
for (const url of urls) {
  const isYt = /youtube\.com|youtu\.be/i.test(url);
  try {
    if (isYt) {
      const vid = (url.match(/(?:v=|youtu\.be\/)([\w-]{11})/) || [])[1];
      let got = false;
      if (vid) {
        const page = await this.helpers.httpRequest({ method: 'GET', url: 'https://www.youtube.com/watch?v=' + vid, timeout: 15000 });
        const m = String(page).match(/"captionTracks":(\[.*?\])/);
        if (m) {
          const tracks = JSON.parse(m[1].replace(/\\u0026/g, '&'));
          if (tracks.length && tracks[0].baseUrl) {
            const xml = await this.helpers.httpRequest({ method: 'GET', url: tracks[0].baseUrl, timeout: 15000 });
            const text = strip(xml).slice(0, 4000);
            if (text) { add({ type: 'youtube', title: 'תמלול סרטון YouTube', text, url, citation: url }); got = true; }
          }
        }
      }
      if (!got) warnings.push('לא נמצא תמלול זמין לסרטון: ' + url);
    } else {
      const html = await this.helpers.httpRequest({ method: 'GET', url, timeout: 15000 });
      const text = strip(html).slice(0, 4000);
      if (text) add({ type: 'url', title: url, text, url, citation: url });
      else warnings.push('לא הצלחתי לחלץ טקסט מהכתובת: ' + url);
    }
  } catch (e) {
    warnings.push('מקור נכשל ודילגתי עליו: ' + url);
  }
}

// 3) Perplexity web search — feature-flagged (only if a key is present in n8n env)
let ppxKey = '';
try { ppxKey = $env.PERPLEXITY_API_KEY || ''; } catch (e) { ppxKey = ''; }
if (ppxKey) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST', url: 'https://api.perplexity.ai/chat/completions',
      headers: { Authorization: 'Bearer ' + ppxKey }, json: true, timeout: 30000,
      body: { model: 'sonar', messages: [{ role: 'user', content: message }] },
    });
    const c = res && res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
    if (c) add({ type: 'web', title: 'חיפוש רשת (Perplexity)', text: c, url: null, citation: 'Perplexity' });
  } catch (e) { warnings.push('חיפוש הרשת נכשל'); }
}

return [{ json: { sources, warnings, count: sources.length } }];
